      const meta: ImportAssetsMeta = {
        id,
        // normalize key to have machine-independent build output
        key: path.relative(resolvedConfig.root, id),
        importerEnvironment: ctx.environment.name,
        isEntry: !!(map[id]?.isEntry || options.isEntry),
